#include <cassert>
#include <iostream>
using namespace day;
Location city(int index){Location l;l.valid=true;l.automatic=false;l.country="US";l.city="City "+std::to_string(index);l.zone="America/New_York";return l;}
int main(){State s;s.countries={{"US","United States",1,true,true,"America/New_York"}};assert(trackedCityCount(s)==1);for(int i=0;i<16;++i)assert(addCountryCity(s,0,city(i)));assert(s.regions.size()==16&&trackedCityCount(s)==16&&s.countries.size()==1);assert(!addCountryCity(s,0,city(16)));assert(addCountryCity(s,0,city(8)));assert(s.regions.size()==16);State restored=decode(encode(s));assert(restored.regions[8].origin==3&&restored.countries[0].cityEnabled);assert(restored.regions.size()==16);removeCountryCity(s,0,0);assert(s.countries[0].clockCity=="City 1"&&s.regions.size()==15&&s.regions[0].origin==1);assert(addCountryCity(s,0,city(16)));removeCountryCity(s,0,5);assert(trackedCityCount(s)==15);while(!s.regions.empty())removeCountryCity(s,0,0);assert(!s.countries[0].cityEnabled&&!s.countries[0].clock&&s.countries[0].holidays);assert(trackedCityCount(s)==0);assert(!decode(encode(s)).countries[0].cityEnabled);assert(addCountryCity(s,0,city(1)));s.countries[0].clock=true;assert(s.countries[0].cityEnabled&&trackedCityCount(s)==1);for(int i=2;i<=16;++i)assert(addCountryCity(s,0,city(i)));assert(setCountryZone(s,0,"America/Chicago"));assert(trackedCityCount(s)==16);assert(addCountryCity(s,0,city(20)));assert(trackedCityCount(s)==16);assert(!addCountryCity(s,0,city(21)));State legacy=s;auto j=encode(legacy);j["countries"][0].erase("cityEnabled");assert(decode(j).countries[0].cityEnabled);std::cout<<"16 cities in one country, limit, deduplication, primary removal, persistence and zone capacity: PASS\n";}
